@pytest.mark.asyncio async def test_cancel_then_reensure_does_not_leak(monkeypatch): """回归测试 Important-1:cancel 后重新 ensure 不丢失 ownership。
场景: 1. ensure() 在 _wait_ready 期间被 cancel → _framework_started=True / _ensured=False 2. 同一 manager 再次 ensure():此时 status() 返回 True(ComfyUI 已在跑) → 若缺少 _framework_started 守卫,会把 ownership 判为"别人起的"并置 False → release() 就不会调用 _spawn_stop → 进程泄漏 3. 有守卫时:_framework_started=True → 跳过 status 探活,直接等 _wait_ready → ensure 完成后 _framework_started 仍为 True 4. release("ensure_release", "run_end") 必须调用 _spawn_stop(不泄漏) """ # 第一次 ensure 用的 status:down(触发 _spawn_serve) # 第二次 ensure 用的 status:up(ComfyUI 已跑起来了) status_results = [False, True] status_call_count = {"n": 0}
async def _status(self): # 按顺序返回预设值 idx = status_call_count["n"] status_call_count["n"] += 1 return status_results[idx] if idx < len(status_results) else True
serve_count = {"n": 0}
async def _serve(self): serve_count["n"] += 1
# 第一次 ensure:_wait_ready 挂起(模拟 cancel 场景) # 第二次 ensure:_wait_ready 立即返回(补完就绪) wait_ready_call_count = {"n": 0}
async def _wait_ready(self): call = wait_ready_call_count["n"] wait_ready_call_count["n"] += 1 if call == 0: # 第一次调用挂起,等待 cancel await asyncio.sleep(100) # 第二次调用立即返回(补完就绪)
stop_count = {"n": 0}
async def _stop(self): stop_count["n"] += 1
monkeypatch.setattr(ComfyLifecycleManager, "status", _status) monkeypatch.setattr(ComfyLifecycleManager, "_spawn_serve", _serve) monkeypatch.setattr(ComfyLifecycleManager, "_wait_ready", _wait_ready) monkeypatch.setattr(ComfyLifecycleManager, "_spawn_stop", _stop)
